-- Turismo Club — 18 : nouvelles offres (itinéraires du marché romain, textes originaux, prix ~5 % sous la concurrence)
-- + catégorie « transfer » (transferts privés, prix par véhicule) et destination Ombrie.
-- Les prix restent modifiables ensuite dans la base ; « Thermes de Dioclétien » = prix sur demande (0 en base).

ALTER TABLE activities DROP CONSTRAINT activities_type_check;
ALTER TABLE activities ADD CONSTRAINT activities_type_check CHECK (type = ANY (ARRAY['activity', 'bus', 'circuit', 'hotel', 'restaurant', 'transfer']));

INSERT INTO destinations (slug, name, is_day_trip) VALUES ('ombrie', 'Ombrie', true) ON CONFLICT (slug) DO NOTHING;

INSERT INTO activities (slug, type, destination_id, title, summary, duration_minutes, max_group_size, min_participants, price_adult_cents, price_child_cents, child_min_age,
  highlights, included, not_included, important_info, meeting_point, badge, times, title_i18n, summary_i18n, is_published) VALUES
('rome-classique', 'activity', (SELECT id FROM destinations WHERE slug = 'rome'), 'Classic Rome guided tour: Trevi, Pantheon, Navona & St Peter''s', 'Three hours through the landmarks of central Rome, partly by open-top bus.', 180, 25, 2, 4200, 4200, NULL,
  ARRAY['Santa Maria Maggiore and the Colosseum', 'Trevi Fountain, Pantheon and Piazza Navona on foot', 'Castel Sant''Angelo and St Peter''s Square']::text[], ARRAY['Licensed local guide', 'Open-top bus ticket for the tour', 'Headsets for groups over 10']::text[], ARRAY['Hotel pick-up', 'Tips']::text[], 'Minimum 2 participants. Runs every morning.', 'Near Termini station (exact address sent with the confirmation)', 'Every morning', ARRAY['09:00']::text[], '{"en":"Classic Rome guided tour: Trevi, Pantheon, Navona & St Peter''s","it":"Roma classica con guida: Trevi, Pantheon, Navona e San Pietro","fr":"Rome classique avec guide : Trevi, Panthéon, Navona & Saint-Pierre","es":"Roma clásica con guía: Trevi, Panteón, Navona y San Pedro","de":"Klassisches Rom mit Guide: Trevi, Pantheon, Navona & Petersplatz","pt":"Roma clássica com guia: Trevi, Panteão, Navona e São Pedro","nl":"Klassiek Rome met gids: Trevi, Pantheon, Navona & Sint-Pieter","zh":"经典罗马导览：特雷维、万神殿、纳沃纳与圣彼得","ja":"クラシック・ローマ ガイドツアー：トレビ、パンテオン、ナヴォーナ、サン・ピエトロ","ko":"클래식 로마 가이드 투어: 트레비, 판테온, 나보나, 성 베드로"}'::jsonb, '{"en":"Three hours through the landmarks of central Rome, partly by open-top bus.","it":"Tre ore tra i simboli del centro di Roma, in parte in bus scoperto.","fr":"Trois heures parmi les monuments phares du centre, en partie en bus à impériale.","es":"Tres horas por los grandes monumentos del centro, en parte en bus descubierto.","de":"Drei Stunden zu den Wahrzeichen der Innenstadt, teils im offenen Bus.","pt":"Três horas pelos marcos do centro de Roma, em parte de autocarro panorâmico.","nl":"Drie uur langs de topmonumenten van het centrum, deels per open bus.","zh":"三小时游览罗马市中心地标，部分路段乘坐敞篷巴士。","ja":"ローマ中心部の名所を3時間で。一部オープントップバスで移動。","ko":"로마 중심의 명소를 3시간 동안, 일부 구간은 오픈탑 버스로."}'::jsonb, true),
('audience-papale', 'activity', (SELECT id FROM destinations WHERE slug = 'rome'), 'General Papal Audience with a local guide', 'See the Pope in St Peter''s Square on Wednesday morning, plus a 1-day hop-on hop-off bus ticket.', 150, 30, NULL, 3400, 3400, NULL,
  ARRAY['Entry to the General Audience', 'Local guide to get you in', 'Free 1-day hop-on hop-off bus ticket']::text[], ARRAY['Local guide', 'Entry to the General Audience', '1-day hop-on hop-off bus ticket']::text[], ARRAY['Hotel pick-up', 'Guaranteed seats']::text[], 'Every Wednesday when the Pope is in Rome. Shoulders and knees covered.', 'Via della Conciliazione 40, Rome', 'Wednesday', ARRAY['07:15']::text[], '{"en":"General Papal Audience with a local guide","it":"Udienza generale del Papa con guida locale","fr":"Audience générale du pape avec guide local","es":"Audiencia general del Papa con guía local","de":"Generalaudienz des Papstes mit lokalem Guide","pt":"Audiência geral do Papa com guia local","nl":"Algemene audiëntie bij de paus met lokale gids","zh":"教皇公开接见（含当地导游）","ja":"ローマ教皇の一般謁見（現地ガイド付き）","ko":"교황 일반 알현 (현지 가이드 동행)"}'::jsonb, '{"en":"See the Pope in St Peter''s Square on Wednesday morning, plus a 1-day hop-on hop-off bus ticket.","it":"Vedere il Papa in Piazza San Pietro il mercoledì mattina, più un biglietto bus hop-on hop-off di 1 giorno.","fr":"Voir le pape place Saint-Pierre le mercredi matin, avec un billet bus hop-on hop-off d''1 jour.","es":"Ver al Papa en la plaza de San Pedro el miércoles por la mañana, con billete de bus hop-on hop-off de 1 día.","de":"Den Papst am Mittwochmorgen auf dem Petersplatz sehen, inklusive 1-Tages-Ticket Hop-on-Hop-off-Bus.","pt":"Ver o Papa na Praça de São Pedro na quarta de manhã, com bilhete de autocarro hop-on hop-off de 1 dia.","nl":"De paus zien op het Sint-Pietersplein op woensdagochtend, met een dagkaart voor de hop-on-hop-offbus.","zh":"周三上午在圣彼得广场见到教皇，另含1日随上随下巴士票。","ja":"水曜朝にサン・ピエトロ広場で教皇に会う。乗り降り自由バス1日券付き。","ko":"수요일 아침 성 베드로 광장에서 교황을 만나고, 1일 홉온 홉오프 버스 승차권 포함."}'::jsonb, true),
('vatican-bus-24h', 'bus', (SELECT id FROM destinations WHERE slug = 'rome'), 'Vatican Museums (afternoon) + hop-on hop-off bus 24 h', 'Afternoon entry to the Vatican Museums and 24 hours of open-top bus around Rome.', 1440, 60, NULL, 6200, 6200, NULL,
  ARRAY['Vatican Museums entry between 2 pm and 6 pm', '24 h unlimited hop-on hop-off', 'Audio guide on the bus in 16 languages']::text[], ARRAY['24 h hop-on hop-off ticket', 'Audio guide on board (16 languages)', 'Vatican Museums afternoon entry (2 pm – 6 pm)']::text[], ARRAY['Hotel pick-up', 'Audio guide inside the Vatican Museums']::text[], 'Non-refundable. Tickets collected near Termini station.', 'Near Termini station (exact address sent with the confirmation)', 'Combo', ARRAY['14:00', '15:00', '16:00']::text[], '{"en":"Vatican Museums (afternoon) + hop-on hop-off bus 24 h","it":"Musei Vaticani (pomeriggio) + bus hop-on hop-off 24 h","fr":"Musées du Vatican (après-midi) + bus hop-on hop-off 24 h","es":"Museos Vaticanos (tarde) + bus hop-on hop-off 24 h","de":"Vatikanische Museen (nachmittags) + Hop-on-Hop-off-Bus 24 Std.","pt":"Museus do Vaticano (tarde) + autocarro hop-on hop-off 24 h","nl":"Vaticaanse Musea (middag) + hop-on-hop-offbus 24 u","zh":"梵蒂冈博物馆（下午场）+ 24小时随上随下巴士","ja":"バチカン美術館（午後入場）＋乗り降り自由バス24時間","ko":"바티칸 박물관(오후 입장) + 24시간 홉온 홉오프 버스"}'::jsonb, '{"en":"Afternoon entry to the Vatican Museums and 24 hours of open-top bus around Rome.","it":"Ingresso pomeridiano ai Musei Vaticani e 24 ore di bus scoperto per Roma.","fr":"Entrée l''après-midi aux musées du Vatican et 24 h de bus à impériale dans Rome.","es":"Entrada de tarde a los Museos Vaticanos y 24 h de bus descubierto por Roma.","de":"Nachmittagseintritt in die Vatikanischen Museen und 24 Std. offener Bus durch Rom.","pt":"Entrada à tarde nos Museus do Vaticano e 24 h de autocarro panorâmico por Roma.","nl":"Middagtoegang tot de Vaticaanse Musea en 24 uur open bus door Rome.","zh":"下午进入梵蒂冈博物馆，再乘敞篷巴士畅游罗马24小时。","ja":"バチカン美術館の午後入場と、ローマを巡るオープントップバス24時間。","ko":"바티칸 박물관 오후 입장과 24시간 오픈탑 버스로 로마 여행."}'::jsonb, true),
('thermes-diocletien-bus', 'bus', (SELECT id FROM destinations WHERE slug = 'rome'), 'Baths of Diocletian (priority entry) + panoramic bus tour', 'The largest baths of ancient Rome and the Palazzo Massimo museum, then one loop of the city by open-top bus.', 240, 60, NULL, 0, 0, NULL,
  ARRAY['Priority entry to the Baths of Diocletian', 'Palazzo Massimo museum included', 'One full loop on the open-top bus']::text[], ARRAY['Entry to the Baths of Diocletian and Palazzo Massimo', 'One loop on the open-top bus', 'Audio guide on board (16 languages)', 'Assistance at the meeting point']::text[], ARRAY['Hotel pick-up', 'Guided tour', 'Food and drinks']::text[], 'Free start time. Price confirmed with your request.', 'Near Termini station (exact address sent with the confirmation)', 'Combo', ARRAY[]::text[], '{"en":"Baths of Diocletian (priority entry) + panoramic bus tour","it":"Terme di Diocleziano (ingresso prioritario) + giro panoramico in bus","fr":"Thermes de Dioclétien (entrée prioritaire) + tour panoramique en bus","es":"Termas de Diocleciano (entrada prioritaria) + tour panorámico en bus","de":"Diokletiansthermen (bevorzugter Eintritt) + Panorama-Bustour","pt":"Termas de Diocleciano (entrada prioritária) + volta panorâmica de autocarro","nl":"Thermen van Diocletianus (voorrangstoegang) + panoramische bustour","zh":"戴克里先浴场（优先入场）+ 全景巴士游","ja":"ディオクレティアヌス浴場（優先入場）＋パノラマバスツアー","ko":"디오클레티아누스 욕장(우선 입장) + 파노라마 버스 투어"}'::jsonb, '{"en":"The largest baths of ancient Rome and the Palazzo Massimo museum, then one loop of the city by open-top bus.","it":"Le terme più grandi dell''antica Roma e Palazzo Massimo, poi un giro della città in bus scoperto.","fr":"Les plus grands thermes de la Rome antique et le musée du Palazzo Massimo, puis un tour de ville en bus à impériale.","es":"Las mayores termas de la Roma antigua y el Palazzo Massimo, y luego una vuelta en bus descubierto.","de":"Die größten Thermen des antiken Rom und der Palazzo Massimo, danach eine Runde im offenen Bus.","pt":"As maiores termas da Roma antiga e o Palazzo Massimo, depois uma volta de autocarro panorâmico.","nl":"De grootste thermen van het oude Rome en Palazzo Massimo, daarna één rondje per open bus.","zh":"参观古罗马最大的浴场和马西莫宫博物馆，再乘敞篷巴士环游一圈。","ja":"古代ローマ最大の浴場とマッシモ宮博物館、その後オープントップバスで市内一周。","ko":"고대 로마 최대의 욕장과 마시모 궁 박물관, 이어서 오픈탑 버스로 시내 한 바퀴."}'::jsonb, true),
('rome-pass-72h', 'bus', (SELECT id FROM destinations WHERE slug = 'rome'), 'Rome Pass 72 h: hop-on hop-off bus, Vatican & Classic Rome tour', 'Three days of open-top bus, the Vatican Museums and a guided walk through the historic centre.', 4320, 60, NULL, 8500, 8500, NULL,
  ARRAY['72 h unlimited hop-on hop-off', 'Vatican Museums entry', 'Guided tour: Trevi, Pantheon, Navona, Barberini, Colosseum']::text[], ARRAY['72 h hop-on hop-off ticket', 'Vatican Museums entry', 'Guided Classic Rome tour']::text[], ARRAY['Hotel pick-up', 'Meals']::text[], 'Times of the Vatican entry and of the guided tour are fixed after booking.', 'Near Termini station (exact address sent with the confirmation)', '72 h', ARRAY[]::text[], '{"en":"Rome Pass 72 h: hop-on hop-off bus, Vatican & Classic Rome tour","it":"Rome Pass 72 h: bus hop-on hop-off, Vaticano e tour di Roma classica","fr":"Rome Pass 72 h : bus hop-on hop-off, Vatican & visite de Rome classique","es":"Rome Pass 72 h: bus hop-on hop-off, Vaticano y tour de Roma clásica","de":"Rome Pass 72 Std.: Hop-on-Hop-off-Bus, Vatikan & Tour durch das klassische Rom","pt":"Rome Pass 72 h: autocarro hop-on hop-off, Vaticano e tour de Roma clássica","nl":"Rome Pass 72 u: hop-on-hop-offbus, Vaticaan & tour door klassiek Rome","zh":"罗马通票72小时：随上随下巴士、梵蒂冈与经典罗马导览","ja":"ローマパス72時間：乗り降り自由バス、バチカン、クラシック・ローマツアー","ko":"로마 패스 72시간: 홉온 홉오프 버스, 바티칸, 클래식 로마 투어"}'::jsonb, '{"en":"Three days of open-top bus, the Vatican Museums and a guided walk through the historic centre.","it":"Tre giorni di bus scoperto, i Musei Vaticani e una passeggiata guidata nel centro storico.","fr":"Trois jours de bus à impériale, les musées du Vatican et une balade guidée dans le centre historique.","es":"Tres días de bus descubierto, los Museos Vaticanos y un paseo guiado por el centro histórico.","de":"Drei Tage offener Bus, die Vatikanischen Museen und ein geführter Rundgang durch die Altstadt.","pt":"Três dias de autocarro panorâmico, os Museus do Vaticano e um passeio guiado pelo centro histórico.","nl":"Drie dagen open bus, de Vaticaanse Musea en een begeleide wandeling door het historische centrum.","zh":"三天敞篷巴士、梵蒂冈博物馆，以及历史中心的导览步行游。","ja":"3日間のオープントップバス、バチカン美術館、歴史地区のガイド付き散策。","ko":"3일간 오픈탑 버스, 바티칸 박물관, 역사 지구 가이드 도보 투어."}'::jsonb, true),
('orvieto-assise', 'circuit', (SELECT id FROM destinations WHERE slug = 'ombrie'), 'Orvieto & Assisi day trip: the land of Saint Francis', 'Two Umbrian hill towns, Lake Trasimeno and a farmhouse lunch with local tastings.', 720, 50, NULL, 16900, 16900, NULL,
  ARRAY['Orvieto by funicular and its cathedral', 'Basilicas of St Francis and St Clare in Assisi', 'Lunch and tastings in a farmhouse by Lake Trasimeno']::text[], ARRAY['Coach', 'Local guide and headsets', 'Lunch and tastings', 'Orvieto funicular', 'Basilica entries', 'Hotel pick-up on request']::text[], ARRAY['Drinks', 'Tips']::text[], 'April–October: Mon, Thu, Fri. November–March: Mon, Thu. Children 0–2 free.', 'Near Termini station at 7:00 (exact address sent with the confirmation)', 'Day trip', ARRAY['07:15']::text[], '{"en":"Orvieto & Assisi day trip: the land of Saint Francis","it":"Orvieto e Assisi in giornata: la terra di San Francesco","fr":"Orvieto & Assise en une journée : la terre de saint François","es":"Orvieto y Asís en un día: la tierra de San Francisco","de":"Tagesausflug Orvieto & Assisi: das Land des heiligen Franziskus","pt":"Orvieto e Assis num dia: a terra de São Francisco","nl":"Dagtrip Orvieto & Assisi: het land van Sint-Franciscus","zh":"奥尔维耶托与阿西西一日游：圣方济各的故乡","ja":"オルヴィエート＆アッシジ日帰り：聖フランチェスコの地","ko":"오르비에토·아시시 당일 여행: 성 프란치스코의 땅"}'::jsonb, '{"en":"Two Umbrian hill towns, Lake Trasimeno and a farmhouse lunch with local tastings.","it":"Due borghi umbri, il lago Trasimeno e pranzo in agriturismo con degustazione.","fr":"Deux villes perchées d''Ombrie, le lac Trasimène et un déjeuner à la ferme avec dégustation.","es":"Dos pueblos de Umbría, el lago Trasimeno y almuerzo en una granja con degustación.","de":"Zwei umbrische Bergstädte, der Trasimenische See und Mittagessen auf einem Bauernhof mit Verkostung.","pt":"Duas vilas da Úmbria, o lago Trasimeno e almoço numa quinta com degustação.","nl":"Twee Umbrische heuvelstadjes, het Trasimeense meer en een lunch op een boerderij met proeverij.","zh":"两座翁布里亚山城、特拉西梅诺湖，以及农庄午餐和特产品尝。","ja":"ウンブリアの2つの丘上都市、トラジメーノ湖、農家レストランでの昼食と試食。","ko":"움브리아의 두 언덕 마을과 트라시메노 호수, 농가 점심과 특산물 시식."}'::jsonb, true),
('sejour-rome-pompei', 'circuit', (SELECT id FROM destinations WHERE slug = 'italie'), 'Rome & Pompeii package: Vatican, Rome by night and Pompeii day trip', 'Airport transfers, 72 h of bus, Vatican, a night bus tour and a full day in Pompeii, in one booking (hotel not included).', 4320, 50, NULL, 32900, 32900, NULL,
  ARRAY['Return airport transfer', 'Vatican Museums & Sistine Chapel', 'Full day in Pompeii with lunch']::text[], ARRAY['Return airport transfer', '72 h hop-on hop-off ticket', 'Vatican Museums & Sistine Chapel', 'Rome by night bus tour', 'Pompeii day trip with site entry', 'Lunch', 'Turismo Club assistance']::text[], ARRAY['Hotel (we can book one for you)', 'Flights']::text[], 'Price per person. Ask us for a hotel and we add it to the quote.', 'Your hotel or the airport', 'Package', ARRAY[]::text[], '{"en":"Rome & Pompeii package: Vatican, Rome by night and Pompeii day trip","it":"Pacchetto Roma e Pompei: Vaticano, Roma di notte e gita a Pompei","fr":"Séjour Rome & Pompéi : Vatican, Rome by night et journée à Pompéi","es":"Paquete Roma y Pompeya: Vaticano, Roma de noche y excursión a Pompeya","de":"Paket Rom & Pompeji: Vatikan, Rom bei Nacht und Tagesausflug nach Pompeji","pt":"Pacote Roma e Pompeia: Vaticano, Roma à noite e dia em Pompeia","nl":"Pakket Rome & Pompeii: Vaticaan, Rome bij nacht en dagtrip naar Pompeii","zh":"罗马与庞贝套餐：梵蒂冈、罗马夜游与庞贝一日游","ja":"ローマ＆ポンペイ パッケージ：バチカン、夜のローマ、ポンペイ日帰り","ko":"로마·폼페이 패키지: 바티칸, 로마 야경, 폼페이 당일 여행"}'::jsonb, '{"en":"Airport transfers, 72 h of bus, Vatican, a night bus tour and a full day in Pompeii, in one booking (hotel not included).","it":"Transfer aeroporto, 72 h di bus, Vaticano, tour notturno e una giornata a Pompei in un''unica prenotazione (hotel escluso).","fr":"Transferts aéroport, 72 h de bus, Vatican, tour de nuit et une journée à Pompéi en une seule réservation (hôtel non inclus).","es":"Traslados al aeropuerto, 72 h de bus, Vaticano, tour nocturno y un día en Pompeya en una sola reserva (hotel no incluido).","de":"Flughafentransfers, 72 Std. Bus, Vatikan, Nachttour und ein Tag in Pompeji – in einer Buchung (ohne Hotel).","pt":"Transferes do aeroporto, 72 h de autocarro, Vaticano, passeio noturno e um dia em Pompeia numa só reserva (hotel não incluído).","nl":"Luchthaventransfers, 72 u bus, Vaticaan, avondtour en een dag in Pompeii in één boeking (hotel niet inbegrepen).","zh":"机场接送、72小时巴士、梵蒂冈、夜游和庞贝一日游，一次预订全部搞定（不含酒店）。","ja":"空港送迎、バス72時間、バチカン、夜のバスツアー、ポンペイ1日観光を一括予約（ホテル別）。","ko":"공항 이동, 72시간 버스, 바티칸, 야간 투어, 폼페이 하루 여행을 한 번에 예약 (호텔 불포함)."}'::jsonb, true),
('sejour-rome-assise', 'circuit', (SELECT id FROM destinations WHERE slug = 'italie'), 'Rome & Assisi package: Vatican, Rome by night and Assisi day trip', 'Airport transfers, 72 h of bus, Vatican, a night bus tour and a full day in Assisi, in one booking (hotel not included).', 4320, 50, NULL, 32900, 32900, NULL,
  ARRAY['Return airport transfer', 'Vatican Museums & Sistine Chapel', 'Full day in Assisi with lunch']::text[], ARRAY['Return airport transfer', '72 h hop-on hop-off ticket', 'Vatican Museums & Sistine Chapel', 'Rome by night bus tour', 'Assisi day trip', 'Lunch', 'Turismo Club assistance']::text[], ARRAY['Hotel (we can book one for you)', 'Flights']::text[], 'Price per person. Ask us for a hotel and we add it to the quote.', 'Your hotel or the airport', 'Package', ARRAY[]::text[], '{"en":"Rome & Assisi package: Vatican, Rome by night and Assisi day trip","it":"Pacchetto Roma e Assisi: Vaticano, Roma di notte e gita ad Assisi","fr":"Séjour Rome & Assise : Vatican, Rome by night et journée à Assise","es":"Paquete Roma y Asís: Vaticano, Roma de noche y excursión a Asís","de":"Paket Rom & Assisi: Vatikan, Rom bei Nacht und Tagesausflug nach Assisi","pt":"Pacote Roma e Assis: Vaticano, Roma à noite e dia em Assis","nl":"Pakket Rome & Assisi: Vaticaan, Rome bij nacht en dagtrip naar Assisi","zh":"罗马与阿西西套餐：梵蒂冈、罗马夜游与阿西西一日游","ja":"ローマ＆アッシジ パッケージ：バチカン、夜のローマ、アッシジ日帰り","ko":"로마·아시시 패키지: 바티칸, 로마 야경, 아시시 당일 여행"}'::jsonb, '{"en":"Airport transfers, 72 h of bus, Vatican, a night bus tour and a full day in Assisi, in one booking (hotel not included).","it":"Transfer aeroporto, 72 h di bus, Vaticano, tour notturno e una giornata ad Assisi in un''unica prenotazione (hotel escluso).","fr":"Transferts aéroport, 72 h de bus, Vatican, tour de nuit et une journée à Assise en une seule réservation (hôtel non inclus).","es":"Traslados al aeropuerto, 72 h de bus, Vaticano, tour nocturno y un día en Asís en una sola reserva (hotel no incluido).","de":"Flughafentransfers, 72 Std. Bus, Vatikan, Nachttour und ein Tag in Assisi – in einer Buchung (ohne Hotel).","pt":"Transferes do aeroporto, 72 h de autocarro, Vaticano, passeio noturno e um dia em Assis numa só reserva (hotel não incluído).","nl":"Luchthaventransfers, 72 u bus, Vaticaan, avondtour en een dag in Assisi in één boeking (hotel niet inbegrepen).","zh":"机场接送、72小时巴士、梵蒂冈、夜游和阿西西一日游，一次预订全部搞定（不含酒店）。","ja":"空港送迎、バス72時間、バチカン、夜のバスツアー、アッシジ1日観光を一括予約（ホテル別）。","ko":"공항 이동, 72시간 버스, 바티칸, 야간 투어, 아시시 하루 여행을 한 번에 예약 (호텔 불포함)."}'::jsonb, true),
('transfert-prive', 'transfer', (SELECT id FROM destinations WHERE slug = 'italie'), 'Private transfers in Italy: airport, station, port, city to city', 'Car with driver for 1–3 people from €84, minivan for 4–6 from €93. Rome ↔ Civitavecchia port and many routes across Italy.', NULL, 6, NULL, 8400, 8400, NULL,
